// ClinicalServiceHandler is an implementation of the healthcare.clinical.v1.ClinicalService
// service.
type ClinicalServiceHandler interface {
	// SRS-CLN-002, SRS-CLN-008, SRS-CLN-009, SRS-CLN-015, SRS-CLN-016. A signed
	// note is never edited: it is amended or extended by an addendum, each a new
	// document that points back.
	WriteNote(context.Context, *connect.Request[v1.WriteNoteRequest]) (*connect.Response[v1.WriteNoteResponse], error)
	SignNote(context.Context, *connect.Request[v1.SignNoteRequest]) (*connect.Response[v1.SignNoteResponse], error)
	AmendNote(context.Context, *connect.Request[v1.AmendNoteRequest]) (*connect.Response[v1.AmendNoteResponse], error)
	RetractNote(context.Context, *connect.Request[v1.RetractNoteRequest]) (*connect.Response[v1.RetractNoteResponse], error)
	GetNote(context.Context, *connect.Request[v1.GetNoteRequest]) (*connect.Response[v1.GetNoteResponse], error)
	ListNotes(context.Context, *connect.Request[v1.ListNotesRequest]) (*connect.Response[v1.ListNotesResponse], error)
	DefineTemplate(context.Context, *connect.Request[v1.DefineTemplateRequest]) (*connect.Response[v1.DefineTemplateResponse], error)
	ListTemplates(context.Context, *connect.Request[v1.ListTemplatesRequest]) (*connect.Response[v1.ListTemplatesResponse], error)
	RetireTemplate(context.Context, *connect.Request[v1.RetireTemplateRequest]) (*connect.Response[v1.RetireTemplateResponse], error)
	// SRS-CLN-015. Expansions are stored into the note, so what is signed is
	// what a reader sees.
	DefineSmartPhrase(context.Context, *connect.Request[v1.DefineSmartPhraseRequest]) (*connect.Response[v1.DefineSmartPhraseResponse], error)
	ListSmartPhrases(context.Context, *connect.Request[v1.ListSmartPhrasesRequest]) (*connect.Response[v1.ListSmartPhrasesResponse], error)
	// SRS-CLN-003. A resolved problem stays on the list as historical.
	RecordProblem(context.Context, *connect.Request[v1.RecordProblemRequest]) (*connect.Response[v1.RecordProblemResponse], error)
	UpdateProblem(context.Context, *connect.Request[v1.UpdateProblemRequest]) (*connect.Response[v1.UpdateProblemResponse], error)
	ListProblems(context.Context, *connect.Request[v1.ListProblemsRequest]) (*connect.Response[v1.ListProblemsResponse], error)
	// SRS-CLN-004. Coded, so medication decision support can check a
	// prescription against it immediately after commit.
	RecordAllergy(context.Context, *connect.Request[v1.RecordAllergyRequest]) (*connect.Response[v1.RecordAllergyResponse], error)
	VerifyAllergy(context.Context, *connect.Request[v1.VerifyAllergyRequest]) (*connect.Response[v1.VerifyAllergyResponse], error)
	ListAllergies(context.Context, *connect.Request[v1.ListAllergiesRequest]) (*connect.Response[v1.ListAllergiesResponse], error)
	// SRS-CLN-005, SRS-CLN-010, SRS-CLN-011. Criticality is supplied by the
	// authoritative diagnostic service and never inferred here.
	RecordObservation(context.Context, *connect.Request[v1.RecordObservationRequest]) (*connect.Response[v1.RecordObservationResponse], error)
	ListObservations(context.Context, *connect.Request[v1.ListObservationsRequest]) (*connect.Response[v1.ListObservationsResponse], error)
	// SRS-CLN-012. Unacknowledged critical results escalate according to policy.
	ListCriticalResults(context.Context, *connect.Request[v1.ListCriticalResultsRequest]) (*connect.Response[v1.ListCriticalResultsResponse], error)
	AcknowledgeCriticalResult(context.Context, *connect.Request[v1.AcknowledgeCriticalResultRequest]) (*connect.Response[v1.AcknowledgeCriticalResultResponse], error)
	// SRS-CLN-006. Laterality is stated rather than assumed, and complications
	// are coded so they can be counted.
	RecordProcedure(context.Context, *connect.Request[v1.RecordProcedureRequest]) (*connect.Response[v1.RecordProcedureResponse], error)
	ListProcedures(context.Context, *connect.Request[v1.ListProceduresRequest]) (*connect.Response[v1.ListProceduresResponse], error)
	// SRS-CLN-007. Activities carry the task id that executes them.
	CreateCarePlan(context.Context, *connect.Request[v1.CreateCarePlanRequest]) (*connect.Response[v1.CreateCarePlanResponse], error)
	UpdateCarePlan(context.Context, *connect.Request[v1.UpdateCarePlanRequest]) (*connect.Response[v1.UpdateCarePlanResponse], error)
	ListCarePlans(context.Context, *connect.Request[v1.ListCarePlansRequest]) (*connect.Response[v1.ListCarePlansResponse], error)
	// SRS-CLN-001. Assembled server-side, because a banner that differs between
	// screens is worse than none.
	GetBanner(context.Context, *connect.Request[v1.GetBannerRequest]) (*connect.Response[v1.GetBannerResponse], error)
	// SRS-CLN-013. Clinical consent, deliberately not the privacy consent of
	// SRS-EMPI-013.
	RecordConsent(context.Context, *connect.Request[v1.RecordConsentRequest]) (*connect.Response[v1.RecordConsentResponse], error)
	WithdrawConsent(context.Context, *connect.Request[v1.WithdrawConsentRequest]) (*connect.Response[v1.WithdrawConsentResponse], error)
	ListConsents(context.Context, *connect.Request[v1.ListConsentsRequest]) (*connect.Response[v1.ListConsentsResponse], error)
	// SRS-CLN-010, SRS-CLN-014. Access follows the parent record and the
	// attachment's own classification.
	AttachFile(context.Context, *connect.Request[v1.AttachFileRequest]) (*connect.Response[v1.AttachFileResponse], error)
	ListAttachments(context.Context, *connect.Request[v1.ListAttachmentsRequest]) (*connect.Response[v1.ListAttachmentsResponse], error)
	GetProvenance(context.Context, *connect.Request[v1.GetProvenanceRequest]) (*connect.Response[v1.GetProvenanceResponse], error)
	// SRS-CLN-020. Recalculation with a new formula never overwrites a
	// historical result.
	StoreCalculation(context.Context, *connect.Request[v1.StoreCalculationRequest]) (*connect.Response[v1.StoreCalculationResponse], error)
	ListCalculations(context.Context, *connect.Request[v1.ListCalculationsRequest]) (*connect.Response[v1.ListCalculationsResponse], error)
	// SRS-CLN-021. Alerts identify the triggering rule and version; overrides are
	// stored and reportable.
	RaiseAlert(context.Context, *connect.Request[v1.RaiseAlertRequest]) (*connect.Response[v1.RaiseAlertResponse], error)
	RespondToAlert(context.Context, *connect.Request[v1.RespondToAlertRequest]) (*connect.Response[v1.RespondToAlertResponse], error)
	ListAlerts(context.Context, *connect.Request[v1.ListAlertsRequest]) (*connect.Response[v1.ListAlertsResponse], error)
	// SRS-CLN-022. The response closes the loop and stays linked to the request.
	RequestConsult(context.Context, *connect.Request[v1.RequestConsultRequest]) (*connect.Response[v1.RequestConsultResponse], error)
	RespondToConsult(context.Context, *connect.Request[v1.RespondToConsultRequest]) (*connect.Response[v1.RespondToConsultResponse], error)
	ListConsults(context.Context, *connect.Request[v1.ListConsultsRequest]) (*connect.Response[v1.ListConsultsResponse], error)
	// SRS-CLN-023. Membership points at canonical clinical facts rather than
	// copying the chart.
	EnrolInRegistry(context.Context, *connect.Request[v1.EnrolInRegistryRequest]) (*connect.Response[v1.EnrolInRegistryResponse], error)
	ExitRegistry(context.Context, *connect.Request[v1.ExitRegistryRequest]) (*connect.Response[v1.ExitRegistryResponse], error)
	ListRegistryMemberships(context.Context, *connect.Request[v1.ListRegistryMembershipsRequest]) (*connect.Response[v1.ListRegistryMembershipsResponse], error)
}

